import{_ as e,o as r,c as o,a2 as n}from"./chunks/framework.Dkj3JE0_.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/JLPT-N2/Quiz/misses.md","filePath":"blogs/JLPT-N2/Quiz/misses.md"}'),a={name:"blogs/JLPT-N2/Quiz/misses.md"};function s(i,t,g,p,h,d){return r(),o("div",null,[...t[0]||(t[0]=[n('<h2 id="_2026-10-13-—-quantifier-ください" tabindex="-1">2026-10-13 — Quantifier + ください <a class="header-anchor" href="#_2026-10-13-—-quantifier-ください" aria-label="Permalink to &quot;2026-10-13 — Quantifier + ください&quot;">​</a></h2><p><strong>Q:</strong> You want two flat tickets — 「Nを2枚ください」 or 「二枚でお願いします」?</p><p><strong>Covered:</strong> Natural order is <strong>Nを2枚ください</strong> (object + を + quantifier + ください). <strong>でお願いします</strong> is for means / chosen option once the item is clear.</p><p><strong>Gap:</strong> Used で where the counting pattern needs を.</p><h2 id="_2026-10-13-—-type-i-polite-negative" tabindex="-1">2026-10-13 — Type I polite negative <a class="header-anchor" href="#_2026-10-13-—-type-i-polite-negative" aria-label="Permalink to &quot;2026-10-13 — Type I polite negative&quot;">​</a></h2><p><strong>Q:</strong> Polite negative of 寒い — and with あまり?</p><p><strong>Covered:</strong> <strong>寒くありません</strong>; <strong>あまり寒くありません</strong>. Not <strong>寒くではありません</strong> (では is Type II / noun).</p><p><strong>Gap:</strong> Mixed Type I く-form with the では negative pattern.</p><h2 id="_2026-10-13-—-も-replaces-を" tabindex="-1">2026-10-13 — も replaces を <a class="header-anchor" href="#_2026-10-13-—-も-replaces-を" aria-label="Permalink to &quot;2026-10-13 — も replaces を&quot;">​</a></h2><p><strong>Q:</strong> Add “hot coffee too” after an order.</p><p><strong>Covered:</strong> <strong>ホットコーヒーもください</strong>. <strong>も</strong> replaces <strong>を</strong> — they do not stack.</p><p><strong>Gap:</strong> Kept を together with も.</p><h2 id="_2026-10-13-—-past-negative-全然" tabindex="-1">2026-10-13 — Past negative + 全然 <a class="header-anchor" href="#_2026-10-13-—-past-negative-全然" aria-label="Permalink to &quot;2026-10-13 — Past negative + 全然&quot;">​</a></h2><p><strong>Q:</strong> Past polite negative with 全然 for 難しい.</p><p><strong>Covered:</strong> <strong>全然難しくありませんでした</strong>. Slip: writing <strong>ではありませんでした</strong> on a Type I adjective.</p><p><strong>Gap:</strong> Past-negative spelling / pattern confusion with Type II–noun では.</p><h2 id="_2026-10-14-—-だれが-→-then-は" tabindex="-1">2026-10-14 — だれが → then は <a class="header-anchor" href="#_2026-10-14-—-だれが-→-then-は" aria-label="Permalink to &quot;2026-10-14 — だれが → then は&quot;">​</a></h2><p><strong>Q:</strong> After だれが留学生ですか, once the person is named, が or は?</p><p><strong>Correct:</strong> Keep が on the identifying answer; later reference uses <strong>は</strong> (known topic). Ex: ジョージさん<strong>は</strong>今、先生の研究室にいます。</p><p><strong>Gap:</strong> Answered with が on the known name.</p><h2 id="_2026-10-14-—-ほしい-third-person" tabindex="-1">2026-10-14 — ほしい third person <a class="header-anchor" href="#_2026-10-14-—-ほしい-third-person" aria-label="Permalink to &quot;2026-10-14 — ほしい third person&quot;">​</a></h2><p><strong>Q:</strong> Third-person “want” with ほしいです?</p><p><strong>Correct:</strong> ほしいです ≈ speaker only. Third person → <strong>ほしがっています</strong>.</p><p><strong>Gap:</strong> Used ほしいです for third person.</p><h2 id="_2026-10-14-—-ほど-ない" tabindex="-1">2026-10-14 — ほど～ない <a class="header-anchor" href="#_2026-10-14-—-ほど-ない" aria-label="Permalink to &quot;2026-10-14 — ほど～ない&quot;">​</a></h2><p><strong>Q:</strong> “Not as … as …” comparison frame?</p><p><strong>Correct:</strong> N₂ は N₁ ほど ～ない（e.g. 日本は中国ほど広くありません）.</p><p><strong>Gap:</strong> より / のほうが solid; ほど～ない missed.</p><h2 id="_2026-10-16-—-帰る-is-a-u-verb" tabindex="-1">2026-10-16 — 帰る is a u-verb <a class="header-anchor" href="#_2026-10-16-—-帰る-is-a-u-verb" aria-label="Permalink to &quot;2026-10-16 — 帰る is a u-verb&quot;">​</a></h2><p><strong>Q:</strong> Is 帰る a ru-verb? What is its ます形?</p><p><strong>Correct:</strong> 帰る looks like a ru-verb but is a <strong>u-verb (godan)</strong>: ます形 <strong>帰ります</strong>.</p><p><strong>Gap:</strong> Treated 帰る as ichidan.</p><h2 id="_2026-10-16-—-advice-ほうがいい" tabindex="-1">2026-10-16 — Advice: ほうがいい <a class="header-anchor" href="#_2026-10-16-—-advice-ほうがいい" aria-label="Permalink to &quot;2026-10-16 — Advice: ほうがいい&quot;">​</a></h2><p><strong>Q:</strong> How do you give advice with a verb vs a noun?</p><p><strong>Correct:</strong> <strong>Vたほうがいい</strong> (休んだほうがいい); for nouns <strong>Nのほうがいい</strong> (水のほうがいい). じゃありませんか is not advice.</p><p><strong>Gap:</strong> Mixed advice with じゃありませんか.</p><h2 id="_2026-10-17-—-nに-marks-the-recipient" tabindex="-1">2026-10-17 — Nに marks the recipient <a class="header-anchor" href="#_2026-10-17-—-nに-marks-the-recipient" aria-label="Permalink to &quot;2026-10-17 — Nに marks the recipient&quot;">​</a></h2><p><strong>Q:</strong> In 中村さんに資料をメールで送りました, who sent and who received?</p><p><strong>Correct:</strong> <strong>Nに</strong> = recipient: “I sent the documents <strong>to</strong> Nakamura-san.” The sender would take <strong>が</strong>.</p><p><strong>Gap:</strong> Read Nakamura as the sender.</p><h2 id="_2026-10-17-—-nなら-for-advice" tabindex="-1">2026-10-17 — Nなら for advice <a class="header-anchor" href="#_2026-10-17-—-nなら-for-advice" aria-label="Permalink to &quot;2026-10-17 — Nなら for advice&quot;">​</a></h2><p><strong>Q:</strong> Reply “If it’s a computer, this one is good.”</p><p><strong>Correct:</strong> <strong>パソコンなら、こちらがいいですよ</strong> / <strong>日本料理なら、駅前の店がいいですよ</strong>. なら picks up the listener’s topic; について just means “about”.</p><p><strong>Gap:</strong> Chose について instead of なら.</p><h2 id="_2026-10-17-—-ほしいなら-vs-ながら" tabindex="-1">2026-10-17 — ほしいなら vs ながら <a class="header-anchor" href="#_2026-10-17-—-ほしいなら-vs-ながら" aria-label="Permalink to &quot;2026-10-17 — ほしいなら vs ながら&quot;">​</a></h2><p><strong>Q:</strong> “If you want one, …”</p><p><strong>Correct:</strong> <strong>ほしいなら</strong>. ながら means “while” and attaches to a verb stem.</p><p><strong>Gap:</strong> Wrote ほしながら.</p><h2 id="_2026-10-17-—-聞く-ask-past-tense" tabindex="-1">2026-10-17 — 聞く: ask, past tense <a class="header-anchor" href="#_2026-10-17-—-聞く-ask-past-tense" aria-label="Permalink to &quot;2026-10-17 — 聞く: ask, past tense&quot;">​</a></h2><p><strong>Q:</strong> “I asked my friend about the plans.”</p><p><strong>Correct:</strong> <strong>友達に予定について聞きました</strong>. 聞く = ask (聴く = listen); past <strong>聞きました</strong>, te-form <strong>聞いて</strong>.</p><p><strong>Gap:</strong> Wrote 聴いでました.</p><h2 id="_2026-10-17-—-スケジュール-spelling" tabindex="-1">2026-10-17 — スケジュール spelling <a class="header-anchor" href="#_2026-10-17-—-スケジュール-spelling" aria-label="Permalink to &quot;2026-10-17 — スケジュール spelling&quot;">​</a></h2><p><strong>Q:</strong> Katakana for “schedule”?</p><p><strong>Correct:</strong> <strong>スケジュール</strong> (ケ, not ゲ).</p><p><strong>Gap:</strong> Wrote スゲジュール.</p><h2 id="_2026-10-17-—-も-after-で" tabindex="-1">2026-10-17 — も after で <a class="header-anchor" href="#_2026-10-17-—-も-after-で" aria-label="Permalink to &quot;2026-10-17 — も after で&quot;">​</a></h2><p><strong>Q:</strong> “I also eat with chopsticks.”</p><p><strong>Correct:</strong> <strong>お箸でも食べます</strong>. も replaces を/が but is added after で/に/と.</p><p><strong>Gap:</strong> Wrote もで.</p><h2 id="_2026-10-18-—-purpose-movement-verb" tabindex="-1">2026-10-18 — Purpose + movement verb <a class="header-anchor" href="#_2026-10-18-—-purpose-movement-verb" aria-label="Permalink to &quot;2026-10-18 — Purpose + movement verb&quot;">​</a></h2><p><strong>Q:</strong> “I went to the library to study Japanese.”</p><p><strong>Correct:</strong> <strong>日本語を勉強しに図書館へ行きました</strong>. Went = 行きました, came = 来ました.</p><p><strong>Gap:</strong> Used the wrong movement verb.</p><h2 id="_2026-10-18-—-い-adjective-noun" tabindex="-1">2026-10-18 — い-adjective + noun <a class="header-anchor" href="#_2026-10-18-—-い-adjective-noun" aria-label="Permalink to &quot;2026-10-18 — い-adjective + noun&quot;">​</a></h2><p><strong>Q:</strong> “a new dictionary”</p><p><strong>Correct:</strong> <strong>新しい辞書</strong>. The い-adjective goes straight onto the noun; 辞書 is everyday, 辞典 more formal.</p><p><strong>Gap:</strong> Wrote 新の辞典.</p><h2 id="_2026-10-18-—-う-verb-negative" tabindex="-1">2026-10-18 — う-verb negative <a class="header-anchor" href="#_2026-10-18-—-う-verb-negative" aria-label="Permalink to &quot;2026-10-18 — う-verb negative&quot;">​</a></h2><p><strong>Q:</strong> Past negative of 買う?</p><p><strong>Correct:</strong> <strong>買わなかった</strong> (う → わ before ない).</p><p><strong>Gap:</strong> Wrote 買いなかった.</p>',72)])])}const u=e(a,[["render",s]]);export{c as __pageData,u as default};
